"""Self-contained immersive Reader presentation."""

READER_TEMPLATE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__ · Panelyra</title><style>
:root{color-scheme:dark;--bg:#05070a;--surface:rgba(15,18,25,.88);--line:#2a303c;--text:#f5f7fb;--muted:#a3adbd;--cyan:#44d8d1;--violet:#8c78ff}*{box-sizing:border-box}html{background:var(--bg);scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 50% -20%,#16202d 0,transparent 38%),var(--bg);color:var(--text);font:14px Inter,ui-sans-serif,system-ui,sans-serif}.bar{position:fixed;z-index:20;top:12px;left:50%;transform:translateX(-50%);width:min(1180px,calc(100% - 24px));display:flex;align-items:center;gap:8px;padding:8px;border:1px solid var(--line);border-radius:14px;background:var(--surface);backdrop-filter:blur(22px);box-shadow:0 16px 55px #0008;transition:.2s}.bar.hidden{opacity:0;transform:translate(-50%,-120%)}.title{min-width:120px;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.title strong{display:block}.title span{color:var(--muted);font-size:11px}.control,select,button{min-height:40px;border:1px solid var(--line);border-radius:10px;background:#171b23;color:var(--text);padding:0 11px;text-decoration:none;font:inherit}.control:hover,select:hover,button:hover{border-color:#657083}.control:focus-visible,select:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #44d8d166;outline-offset:2px}.disabled{opacity:.35;pointer-events:none}.reader{padding:78px 0 180px;display:flex;flex-direction:column;align-items:center;min-height:100vh}.panel{position:relative;margin:0;line-height:0;content-visibility:auto;contain-intrinsic-size:auto var(--panel-height);background:#090b10}.panel img{display:block;width:100%;height:auto}.fit .panel{width:min(100%,1120px)}.comfort .panel{width:min(100%,880px)}.original .panel{width:auto;max-width:100%}.single,.double{gap:18px;padding-left:12px;padding-right:12px}.single .panel{display:none;width:min(100%,900px)}.single .panel.active{display:block}.double{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:start;max-width:1400px;margin:auto}.double .panel{width:100%}.loading{position:absolute;inset:0;display:grid;place-items:center;line-height:1.3;color:var(--muted)}.panel.loaded .loading{display:none}.image-error{display:none;line-height:1.45;padding:28px;text-align:center;background:#17121a;min-height:180px}.panel.failed .image-error{display:block}.panel.failed img,.panel.failed .loading{display:none}.image-error span{display:block;color:var(--muted);margin:7px}.dock{position:fixed;z-index:18;left:50%;bottom:14px;transform:translateX(-50%);width:min(760px,calc(100% - 24px));padding:8px 10px;border:1px solid var(--line);border-radius:14px;background:var(--surface);backdrop-filter:blur(20px);box-shadow:0 16px 50px #0008}.rail{display:flex;align-items:center;gap:10px}.rail input{flex:1;accent-color:var(--cyan)}.rail span{min-width:112px;text-align:right;color:var(--muted);font-size:12px}.modes{display:flex;gap:6px;margin-top:6px;justify-content:center}.mode.active{border-color:var(--cyan);color:var(--cyan)}.end{margin:30px auto 0;width:min(620px,calc(100% - 24px));padding:32px;border:1px solid var(--line);border-radius:18px;background:#11151d;text-align:center}.end p{color:var(--muted)}.end-actions{display:flex;flex-wrap:wrap;justify-content:center;gap:8px}.lyra-glyph{display:inline-block;width:19px;height:19px;background:linear-gradient(145deg,#61ece2,#9a7cff);clip-path:polygon(50% 0,61% 37%,100% 50%,61% 63%,50% 100%,39% 63%,0 50%,39% 37%)}.lyra-toggle{display:flex;align-items:center;gap:7px;background:linear-gradient(135deg,#183d47,#33295d)}.shortcuts{position:fixed;z-index:40;inset:0;background:#0009;display:grid;place-items:center}.shortcuts[hidden]{display:none}.shortcut-card{width:min(520px,calc(100% - 24px));padding:24px;border:1px solid var(--line);border-radius:18px;background:#121620}.shortcut-card kbd{color:var(--cyan)}@media(max-width:760px){.bar{top:6px;overflow-x:auto}.title{display:none}.nav-label,.lyra-toggle span:last-child{display:none}.reader{padding-top:64px}.fit .panel,.comfort .panel{width:100%}.double{grid-template-columns:1fr}.dock{bottom:7px}.modes{overflow-x:auto;justify-content:flex-start}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style></head><body><header class="bar" id="bar"><a class="control" href="__LIBRARY__">Library</a><a class="control nav-label __PREVIOUS_CLASS__" aria-disabled="__PREVIOUS_DISABLED__" href="__PREVIOUS__">Previous</a><div class="title"><strong>__TITLE__</strong><span>__EDITION__ · Chapter __CHAPTER__</span></div><select id="chapter" aria-label="Choose chapter">__OPTIONS__</select><a class="control nav-label __NEXT_CLASS__" aria-disabled="__NEXT_DISABLED__" href="__NEXT__">Next</a><select id="edition" aria-label="Choose edition">__EDITION_OPTIONS__</select><button class="control" id="fullscreen" aria-label="Toggle fullscreen">Full</button>__LYRA_BUTTON__</header><main id="reader" class="reader fit">__IMAGES__<section class="end" id="chapter-end"><h2>End of Chapter __CHAPTER__</h2><p>Panelyra will never move you to another chapter without your choice.</p><div class="end-actions"><a class="control __NEXT_CLASS__" href="__NEXT__">Next Chapter</a><a class="control" href="__LIBRARY__">Back to Library</a><button id="complete">Mark Complete</button><a class="control" href="__CLEANER__">Trim page edges</a></div></section></main><footer class="dock"><div class="rail"><span id="position">Panel 1 of __TOTAL__</span><input id="jump" type="range" min="1" max="__TOTAL__" value="1" aria-label="Reading position"><span id="percent">0%</span></div><div class="modes"><button class="mode active" data-mode="fit">Fit</button><button class="mode" data-mode="comfort">Comfort</button><button class="mode" data-mode="original">Original</button><button class="mode" data-mode="single">Single</button><button class="mode" data-mode="double">Double</button><button id="help">Shortcuts</button></div></footer>__LYRA_PANEL__<div class="shortcuts" id="shortcuts" hidden><div class="shortcut-card"><h2>Reader shortcuts</h2><p><kbd>J / K</kbd> move · <kbd>← / →</kbd> chapters · <kbd>G</kbd> chapter list · <kbd>F</kbd> fullscreen · <kbd>?</kbd> help</p><button id="close-help">Close</button></div></div><script>
const state=__PAYLOAD__,reader=document.querySelector('#reader'),panels=[...document.querySelectorAll('.panel')],bar=document.querySelector('#bar'),jump=document.querySelector('#jump'),pos=document.querySelector('#position'),pct=document.querySelector('#percent');let current=1,mode='fit',completed=false,restoring=true,lastSave=0,endTimer=null,launcher=document.querySelector('#lyra-toggle');const localKey=state.key;
function snapshot(){return{series:state.baseSeries,chapter:state.chapter,edition:state.edition,panel:current,total_panels:state.total,percent:Math.round(1000*Math.max(scrollY,0)/Math.max(1,document.documentElement.scrollHeight-innerHeight))/10,offset:Math.round(scrollY),mode,completed,updated_at:Date.now()/1000}}
function localRead(){try{return JSON.parse(localStorage.getItem(localKey)||'null')}catch{return null}}function localWrite(x){localStorage.setItem(localKey,JSON.stringify(x))}
async function save(force=false){if(restoring||(!force&&Date.now()-lastSave<1200))return;lastSave=Date.now();const x=snapshot();localWrite(x);try{await fetch('/api/progress',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...x,reader_token:state.readerToken}),keepalive:true})}catch{}}
async function restore(){let remote=null;try{const q=new URLSearchParams({reader_token:state.readerToken,series:state.baseSeries,chapter:state.chapter,edition:state.edition});remote=await(await fetch('/api/progress?'+q)).json()}catch{}const local=localRead(),best=(remote?.updated_at||0)>(local?.updated_at||0)?remote:local;if(best){completed=!!best.completed;current=Math.max(1,Math.min(state.total,best.panel||1));setMode(best.mode||'fit');requestAnimationFrame(()=>{scrollTo(0,best.offset||0);restoring=false;update()})}else{setMode('fit');restoring=false;update()}}
function setMode(next){mode=['fit','comfort','original','single','double'].includes(next)?next:'fit';reader.className='reader '+mode;document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x.dataset.mode===mode));showPaged()}
function showPaged(){panels.forEach((p,i)=>p.classList.toggle('active',mode!=='single'||i===current-1))}function goPanel(n){current=Math.max(1,Math.min(state.total,n));showPaged();panels[current-1]?.scrollIntoView({block:'start'});update()}
function update(){pos.textContent=`Panel ${current} of ${state.total}`;jump.value=current;pct.textContent=snapshot().percent+'%'}
document.querySelector('#chapter').onchange=e=>{save(true);const q=new URLSearchParams({edition:state.edition,series:state.series,chapter:e.target.value,reader_token:state.readerToken});if(state.lyraToken)q.set('lyra',state.lyraToken);location.href='/reader?'+q};document.querySelector('#edition').onchange=e=>{save(true);location.href=e.target.value};document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{setMode(b.dataset.mode);save(true)});jump.oninput=e=>goPanel(+e.target.value);document.querySelector('#fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen?.();
const io=new IntersectionObserver(entries=>{const best=entries.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(best){current=+best.target.dataset.panel;update();save();if(current===state.total){clearTimeout(endTimer);endTimer=setTimeout(()=>document.querySelector('#chapter-end').dataset.reached='true',1800)}}},{threshold:[.25,.55,.8]});panels.forEach(p=>{io.observe(p);const img=p.querySelector('img');img.onload=()=>{p.classList.remove('failed');p.classList.add('loaded')};img.onerror=()=>p.classList.add('failed');if(img.complete){if(img.naturalWidth)p.classList.add('loaded');else p.classList.add('failed')}p.querySelector('.retry-image').onclick=()=>{p.classList.remove('failed');img.src=img.src.split('?')[0]+'?retry='+Date.now()}});
document.querySelector('#complete').onclick=async()=>{await fetch('/api/read-state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reader_token:state.readerToken,series:state.baseSeries,chapter:state.chapter,edition:state.edition,completed:true})});completed=true;localWrite(snapshot());document.querySelector('#complete').textContent='Completed'};document.querySelector('#help').onclick=()=>document.querySelector('#shortcuts').hidden=false;document.querySelector('#close-help').onclick=()=>document.querySelector('#shortcuts').hidden=true;
let controlsHidden=false;const chromeStyle=document.createElement('style');chromeStyle.textContent='body.controls-hidden #bar,body.controls-hidden .dock,body.controls-hidden .progress,body.controls-hidden #chapter-end,body.controls-hidden #shortcuts,body.controls-hidden #lyra-panel{visibility:hidden!important;opacity:0!important;pointer-events:none!important}.control,button{display:inline-flex;align-items:center;justify-content:center;text-align:center;line-height:1.15;height:40px;min-height:40px;vertical-align:middle}.bar select{height:40px;line-height:normal;text-align:center;text-align-last:center}.modes button{min-width:58px;flex-shrink:0}.rail span:last-child{min-width:42px}';document.head.append(chromeStyle);function reveal(){if(!controlsHidden)bar.classList.remove('hidden')}document.addEventListener('click',e=>{if(e.target.closest('button,a,input,select,textarea,#bar,.dock,.progress,#shortcuts,#lyra-panel,#chapter-end'))return;if(getSelection()?.toString())return;controlsHidden=!controlsHidden;document.body.classList.toggle('controls-hidden',controlsHidden);bar.classList.remove('hidden')});
addEventListener('keydown',e=>{if(/input|textarea|select/i.test(e.target.tagName))return;const k=e.key.toLowerCase();if(['ArrowDown','ArrowUp','PageDown','PageUp','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();if(k==='j'||e.key==='ArrowDown'||e.key==='PageDown')mode==='single'?goPanel(current+1):scrollBy({top:innerHeight*.82,behavior:'smooth'});if(k==='k'||e.key==='ArrowUp'||e.key==='PageUp')mode==='single'?goPanel(current-1):scrollBy({top:-innerHeight*.82,behavior:'smooth'});if(e.key==='ArrowLeft'&&state.previous!=='#'){save(true);location.href=state.previous}if(e.key==='ArrowRight'&&state.next!=='#'){save(true);location.href=state.next}if(k==='g')document.querySelector('#chapter').focus();if(k==='f')document.querySelector('#fullscreen').click();if(k==='l')launcher?.click();if(k==='?')document.querySelector('#shortcuts').hidden=false;if(e.key==='Escape'){document.querySelector('#shortcuts').hidden=true;closeLyra()}});addEventListener('pagehide',()=>save(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)save(true)});restore();
function closeLyra(){const p=document.querySelector('#lyra-panel');if(p&&!p.hidden){p.hidden=true;launcher?.focus()}}if(state.lyraToken){const p=document.querySelector('#lyra-panel'),m=document.querySelector('#lyra-messages'),i=document.querySelector('#lyra-input');launcher.onclick=()=>{p.hidden=false;i.focus();reveal()};document.querySelector('#lyra-close').onclick=closeLyra;document.querySelectorAll('.lyra-prompt').forEach(b=>b.onclick=()=>{i.value=b.textContent;i.focus()});document.querySelector('#lyra-form').onsubmit=async e=>{e.preventDefault();const q=i.value.trim();if(!q)return;const u=document.createElement('div'),a=document.createElement('div');u.className='lyra-user';a.className='lyra-answer';u.textContent=q;m.append(u,a);i.value='';try{const r=await fetch('/api/lyra/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:state.lyraToken,prompt:q,edition:state.edition,series:state.series,chapter:state.chapter,panel:current})});if(!r.ok)throw Error();const rd=r.body.getReader(),d=new TextDecoder();let b='';while(true){const x=await rd.read();b+=d.decode(x.value||new Uint8Array(),{stream:!x.done});const lines=b.split('\n');b=lines.pop();for(const line of lines){if(!line)continue;const o=JSON.parse(line);if(o.chunk)a.textContent+=o.chunk;if(o.error&&!a.textContent)a.textContent='Local AI is unavailable.'}if(x.done)break}}catch{a.textContent='Lyra is unavailable right now.'}m.scrollTop=m.scrollHeight}}
</script></body></html>'''

LYRA_PANEL = r'''<aside id="lyra-panel" class="lyra-panel" hidden aria-label="Ask Lyra"><header><span class="lyra-glyph" aria-hidden="true"></span><div><strong>Lyra</strong><small>Local AI · Private on this Mac</small></div><button id="lyra-close" aria-label="Close Lyra">×</button></header><div class="lyra-prompts"><button class="lyra-prompt">What does this Reader control do?</button><button class="lyra-prompt">Why is this image missing?</button><button class="lyra-prompt">Which edition am I reading?</button></div><div id="lyra-messages" class="lyra-messages"><div class="lyra-answer">I can explain Reader controls, editions, progress, and local file errors. I cannot see or interpret the artwork itself.</div></div><form id="lyra-form"><textarea id="lyra-input" rows="2" aria-label="Message Lyra" placeholder="Ask about this chapter…"></textarea><button>Send</button></form></aside><style>.lyra-panel{position:fixed;z-index:35;right:16px;top:74px;width:min(400px,calc(100vw - 24px));height:min(620px,calc(100vh - 100px));display:flex;flex-direction:column;border:1px solid var(--line);border-radius:18px;background:#10141c;box-shadow:0 28px 90px #000b;overflow:hidden}.lyra-panel[hidden]{display:none}.lyra-panel header{display:flex;align-items:center;gap:10px;padding:13px;border-bottom:1px solid var(--line)}.lyra-panel header div{flex:1}.lyra-panel small{display:block;color:var(--muted);margin-top:2px}.lyra-panel header button{font-size:20px}.lyra-prompts{display:flex;gap:6px;padding:10px;overflow-x:auto}.lyra-prompt{white-space:nowrap;font-size:12px;min-height:34px}.lyra-messages{flex:1;overflow:auto;padding:13px;line-height:1.55}.lyra-user,.lyra-answer{padding:10px 12px;margin:8px 0;border-radius:12px;white-space:pre-wrap}.lyra-user{margin-left:20%;background:#282d3c}.lyra-answer{margin-right:6%;background:#181d27}.lyra-panel form{display:flex;align-items:end;gap:8px;padding:10px;border-top:1px solid var(--line)}.lyra-panel textarea{flex:1;resize:none;border:1px solid var(--line);border-radius:11px;background:#090c11;color:#fff;padding:9px;font:inherit}@media(max-width:700px){.lyra-panel{inset:auto 6px 6px;width:auto;height:min(68vh,560px)}}</style>'''
